import{_ as a,o as n,a as p,b as l}from"./app.BGziXukh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"RTC","link":"/api/Utils-API/RTC/RTC"},{"text":"aclrtcKernelSpecialization","link":"/api/Utils-API/RTC/aclrtcKernelSpecialization"}]},"headers":[],"relativePath":"api/Utils-API/RTC/aclrtcKernelSpecialization.md","filePath":"api/Utils-API/RTC/aclrtcKernelSpecialization.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"aclrtcKernelSpecRequest","slug":"aclrtcKernelSpecRequest","link":"#aclrtcKernelSpecRequest"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1794990053000}'),c={name:"api/Utils-API/RTC/aclrtcKernelSpecialization.md"};function e(t,s,r,i,o,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>aclrtcKernelSpecialization</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>使用指定的常量参数进行常量化编译，并将生成的Kernel ELF文件保存至指定路径。</p><p>常量化编译将Tiling等参数值作为编译期常量，使编译器可进行常量传播、常量折叠和分支消除。此类优化可减少运行时的参数计算和条件判断，其性能收益可体现为Scalar执行耗时的降低。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">aclError</span><span class="w"> </span><span class="n">aclrtcKernelSpecialization</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">aclrtcKernelSpecRequest</span><span class="w"> </span><span class="o">*</span><span class="n">request</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="o">*</span><span class="n">outPath</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">request</td><td align="center">输入</td><td align="left">Kernel常量化编译请求，不能为空。各成员的配置要求请参见<a href="#table-aclrtc-kernel-spec-request">表2</a>。</td></tr><tr><td align="left">outPath</td><td align="center">输入</td><td align="left">特化Kernel ELF的输出文件路径，不能为空指针或空字符串。</td></tr></tbody></table><h3 id="aclrtcKernelSpecRequest">aclrtcKernelSpecRequest<a class="header-anchor" href="#aclrtcKernelSpecRequest">​</a></h3><p><code>aclrtcKernelSpecRequest</code>定义位于<code>&quot;acl/acl_rt_compile.h&quot;</code>。</p><p><strong>表2</strong> aclrtcKernelSpecRequest成员说明<a id="table-aclrtc-kernel-spec-request"></a></p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">resourceId</td><td align="left">常量化编译资源标识，取资源Manifest中的<code>resource_id</code>，须精确匹配，不能为空指针或空字符串。Manifest为构建算子包时生成的常量化编译资源清单，获取方式请参见<a href="../../../guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.html#kernel-spec">生成Kernel Spec常量化编译资源</a>。</td></tr><tr><td align="left">kernelEntry</td><td align="left">待常量化Kernel的原始入口名称，取资源Manifest中的<code>kernel_name</code>，须精确匹配。不能为空指针或空字符串。</td></tr><tr><td align="left">outputKernelEntry</td><td align="left">指出编译产物中的Kernel入口名称。传入<code>nullptr</code>或空字符串时，沿用<code>kernelEntry</code>。指定名称不得包含逗号或ASCII控制字符，且不能以<code>mix_aic</code>或<code>mix_aiv</code>结尾。</td></tr><tr><td align="left">argsCount</td><td align="left"><code>argsAddr</code>的元素个数，包含用<code>nullptr</code>占位的元素。每个待常量化参数的下标均须小于此值。</td></tr><tr><td align="left">argsAddr</td><td align="left">数据地址数组，按<code>kernelEntry</code>指定的核函数（Kernel）的参数顺序填写，下标从0开始。对Manifest指定的待常量化参数，填写其实际数据在Host上的地址；其余位置可填<code>nullptr</code>。</td></tr><tr><td align="left">argsBytes</td><td align="left">数据长度数组，单位为字节，顺序与<code>argsAddr</code>一致。待常量化参数在Manifest中的<code>arg_type</code>为<code>struct</code>（默认值）时，填写实际数据长度，且须大于0；为<code>pointer</code>时，长度由Manifest指定。若所有待常量化参数的<code>arg_type</code>均为<code>pointer</code>，本参数可传入<code>nullptr</code>。</td></tr><tr><td align="left">options</td><td align="left">为本次常量化编译追加的编译选项。<code>optionCount</code>为0时，可传入<code>nullptr</code>；大于0时，须提供选项数组，且每个元素都须指向非空字符串。</td></tr><tr><td align="left">optionCount</td><td align="left"><code>options</code>数组的元素个数。</td></tr><tr><td align="left">skOptions</td><td align="left">SuperKernel编译选项数组，不用于链接。在数组中加入<code>--enable-super-kernel</code>可启用SuperKernel编译，其余选项用于编译SuperKernel对象。未设置该选项时，忽略数组中的其他选项。该选项只能设置一次。<code>skOptionCount</code>为0时，可传入<code>nullptr</code>。大于0时，须提供编译选项数组，且每个元素都须指向非空字符串。</td></tr><tr><td align="left">skOptionCount</td><td align="left"><code>skOptions</code>数组的元素个数。</td></tr><tr><td align="left">reserved</td><td align="left">保留字段，当前版本必须全部置为0。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>aclError为int类型变量，详细说明请参考<a href="RTC_error_code.html">RTC错误码</a>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>当前仅支持对通过aclnn接口调用的算子进行常量化编译，不支持通过<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>语法直接调用的Kernel。</li><li>当前不支持对包含可选参数（Optional）的算子进行常量化编译。</li><li>调用前须确保<code>resourceId</code>对应的常量化编译资源已注册且可被运行时发现，<code>kernelEntry</code>在该资源中存在，参数数据类型及布局与该资源的常量参数声明一致。</li><li><code>request</code>及其引用的字符串、数组和参数数据须在本次同步调用期间保持有效且不可修改。调用返回后可释放请求数组和常量参数缓冲区，接口不会替调用方释放这些内存。</li><li>待常量化参数的Host缓冲区可读长度须不小于接口读取的数据长度。</li><li><code>resourceId</code>、<code>kernelEntry</code>、<code>outPath</code>及各编译选项均须为空字符结尾的字符串；指定<code>outputKernelEntry</code>时，该字段也须为空字符结尾的字符串。每个字符串内容长度不超过1MiB，全部字符串内容的累计长度不超过4MiB，长度均不计结尾空字符。</li><li>每个编译选项字符串作为一个完整参数传递，不按空格拆分。</li><li>调用期间，调用方不应读取或替换outPath指定的输出文件。</li><li>编译资源须在调用前通过<a href="../../../guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.html#npu_op_package">CMake接口</a>配置并在算子包构建时生成。本接口仅使用该资源进行常量化编译，并输出生成的ELF文件。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下片段展示MatmulCustom样例的常量化编译请求配置。MatmulCustom有5个Kernel参数，仅将第5个参数<code>tiling</code>作为常量参数。调用前按样例准备编译资源，从其Manifest获取<code>resource_id</code>和<code>kernel_name</code>，分别传入<code>resourceId</code>和<code>kernelEntry</code>；使用Matmul Tiling API为<code>M = N = K = 512</code>生成Tiling参数，并通过<code>SaveToBuffer</code>写入Host侧的<code>tiling</code>缓冲区。示例通过<code>options</code>分别传入<code>-g</code>和<code>-fno-ident</code>，用于生成调试信息并禁止生成编译器标识信息。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl_rt_compile.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tiling/tiling_api.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;array&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdio&gt;</span>

<span class="n">aclError</span><span class="w"> </span><span class="nf">SpecializeMatmulCustom</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">resourceId</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">kernelEntry</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">outPath</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">std</span><span class="o">::</span><span class="n">array</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="p">,</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">tiling</span><span class="o">::</span><span class="n">TCubeTiling</span><span class="p">)</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 仅传入第5个参数的Host数据，其他位置用nullptr占位。</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">argsAddr</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">data</span><span class="p">()};</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">argsBytes</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">tiling</span><span class="p">)};</span>

<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">options</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="s">&quot;-g&quot;</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;-fno-ident&quot;</span><span class="p">};</span>
<span class="w">    </span><span class="n">aclrtcKernelSpecRequest</span><span class="w"> </span><span class="n">request</span><span class="p">{};</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">resourceId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">resourceId</span><span class="p">;</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">kernelEntry</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">kernelEntry</span><span class="p">;</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">argsCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">;</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">argsAddr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">argsAddr</span><span class="p">;</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">argsBytes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">argsBytes</span><span class="p">;</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">options</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">options</span><span class="p">;</span>
<span class="w">    </span><span class="n">request</span><span class="p">.</span><span class="n">optionCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>

<span class="w">    </span><span class="n">aclError</span><span class="w"> </span><span class="n">ret</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">aclrtcKernelSpecialization</span><span class="p">(</span><span class="o">&amp;</span><span class="n">request</span><span class="p">,</span><span class="w"> </span><span class="n">outPath</span><span class="p">);</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ret</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="n">ACL_SUCCESS</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">std</span><span class="o">::</span><span class="n">fprintf</span><span class="p">(</span><span class="n">stderr</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;aclrtcKernelSpecialization failed: %d</span><span class="se">\\n</span><span class="s">&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">ret</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">ret</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const g=a(c,[["render",e]]);export{h as __pageData,g as default};
